// 원시값 (Primitive)
let a = 10;
let b = a;
b = 20;
console.log(a, b);

// 참조값 (Reference)
let obj1 = { value: 10 };
let obj2 = obj1;
obj2.value = 20;
console.log(obj1.value, obj2.value);

